import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); // super light + stable

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;500;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type LiquidGlassOverlayProps = Record<string, any>;

const LiquidGlassOverlay: React.FC<LiquidGlassOverlayProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 5,
  dayOfWeek = "Thursday",
  dateNumber = "23",
  appTitle = "CALENDAR",
  eventTitle = "Ketone IQ First Meeting",
  locationLine1 = "DOAC Studio",
  locationLine2 = "Los Angeles, CA",
  accentColor = "#9b51e0",
  cardOpacity = 0.65,
  blurAmount = 24,
  cardScale = 1.0,
}) => {

  {/* Load Google Fonts */ }
  useFontLoader(["Inter"]);
  {/* End Load Google Fonts */ }

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Relative sizing baseline
  const baseSize = Math.min(width, height) * 0.01;

  // --- Animations ---
  
  // 1. Main Card Liquid Intro
  // Staggered X and Y springs create a jelly/liquid wobble on entry
  const scaleX = spring({
    fps,
    frame: frame - 5,
    config: { damping: 12, stiffness: 100, mass: 1 },
  });
  
  const scaleY = spring({
    fps,
    frame: frame - 8,
    config: { damping: 10, stiffness: 90, mass: 1 },
  });

  const entryY = interpolate(
    spring({ fps, frame: frame - 5, config: { damping: 14, stiffness: 80 } }),
    [0, 1],
    [100, 0]
  );

  const cardAlpha = interpolate(frame, [5, 15], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });

  // 2. Content Stagger Springs
  const useStaggeredSpring = (delayFrames: number) => {
    return spring({
      fps,
      frame: frame - delayFrames,
      config: { damping: 14, stiffness: 80 },
    });
  };

  const headerSpring = useStaggeredSpring(12);
  const accentSpring = useStaggeredSpring(18);
  const titleSpring = useStaggeredSpring(22);
  const loc1Spring = useStaggeredSpring(26);
  const loc2Spring = useStaggeredSpring(30);

  // 3. Outro Animation
  const outroStartFrame = (durationInSeconds * fps) - 20;
  const globalOpacity = interpolate(
    frame,
    [outroStartFrame, outroStartFrame + 15],
    [1, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Dynamic Styles
  const glassCardStyle: React.CSSProperties = {
    width: `${width * 0.6}px`,
    backgroundColor: `rgba(20, 20, 25, ${cardOpacity})`,
    backdropFilter: `blur(${blurAmount}px)`,
    WebkitBackdropFilter: `blur(${blurAmount}px)`, // Safari support
    borderRadius: `${baseSize * 4}px`,
    padding: `${baseSize * 5}px`,
    display: "flex",
    flexDirection: "column",
    gap: `${baseSize * 4}px`,
    border: "1px solid rgba(255, 255, 255, 0.15)",
    boxShadow: "0 32px 64px rgba(0,0,0,0.3), inset 0 1px 0 rgba(255,255,255,0.1)",
    transform: `translateY(${entryY}px) scale(${scaleX * cardScale}, ${scaleY * cardScale})`,
    opacity: cardAlpha,
    overflow: "hidden", // Ensures accent line doesn't poke out during liquid bounce
  };

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Inter", justifyContent: "center", alignItems: "center", opacity: globalOpacity }}>
      
      {/* Main Glass Container */}
      <div style={glassCardStyle}>
        
        {/* Header Row */}
        <div style={{
          display: "flex",
          flexDirection: "row",
          alignItems: "center",
          gap: `${baseSize * 2}px`,
          opacity: headerSpring,
          transform: `translateX(${interpolate(headerSpring, [0, 1], [-20, 0])}px)`,
        }}>
          {/* Calendar Icon Badge */}
          <div style={{
            backgroundColor: "#ffffff",
            borderRadius: `${baseSize * 1.5}px`,
            padding: `${baseSize * 0.8}px ${baseSize * 1.2}px`,
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            justifyContent: "center",
            minWidth: `${baseSize * 6}px`,
            boxShadow: "0 4px 12px rgba(0,0,0,0.1)",
          }}>
            <span style={{ color: "#d93838", fontSize: `${baseSize * 1.2}px`, fontWeight: 700, letterSpacing: "-0.02em" }}>
              {dayOfWeek}
            </span>
            <span style={{ color: "#111111", fontSize: `${baseSize * 3.5}px`, fontWeight: 600, lineHeight: 1, marginTop: `${baseSize * 0.2}px` }}>
              {dateNumber}
            </span>
          </div>

          {/* App Title */}
          <span style={{
            color: "#ffffff",
            fontSize: `${baseSize * 2.8}px`,
            fontWeight: 600,
            letterSpacing: "0.05em",
          }}>
            {appTitle}
          </span>
        </div>

        {/* Content Body Row */}
        <div style={{
          display: "flex",
          flexDirection: "row",
          alignItems: "stretch",
          marginTop: `${baseSize * 2}px`,
        }}>
          
          {/* Vertical Accent Line */}
          <div style={{
            width: `${baseSize * 0.6}px`,
            backgroundColor: accentColor,
            borderRadius: `${baseSize * 0.3}px`,
            marginRight: `${baseSize * 2.5}px`,
            transform: `scaleY(${accentSpring})`,
            transformOrigin: "top",
            boxShadow: `0 0 12px ${accentColor}80`, // Subtle glow
          }} />

          {/* Text Content Column */}
          <div style={{
            display: "flex",
            flexDirection: "column",
            justifyContent: "center",
          }}>
            <h1 style={{
              margin: 0,
              color: "#ffffff",
              fontSize: `${baseSize * 4.5}px`,
              fontWeight: 700,
              letterSpacing: "-0.02em",
              lineHeight: 1.1,
              opacity: titleSpring,
              transform: `translateY(${interpolate(titleSpring, [0, 1], [10, 0])}px)`,
            }}>
              {eventTitle}
            </h1>
            
            <p style={{
              margin: `${baseSize * 1}px 0 0 0`,
              color: "#cccccc",
              fontSize: `${baseSize * 3}px`,
              fontWeight: 400,
              opacity: loc1Spring,
              transform: `translateY(${interpolate(loc1Spring, [0, 1], [10, 0])}px)`,
            }}>
              {locationLine1}
            </p>
            
            <p style={{
              margin: `${baseSize * 0.2}px 0 0 0`,
              color: "#cccccc",
              fontSize: `${baseSize * 3}px`,
              fontWeight: 400,
              opacity: loc2Spring,
              transform: `translateY(${interpolate(loc2Spring, [0, 1], [10, 0])}px)`,
            }}>
              {locationLine2}
            </p>
          </div>

        </div>
      </div>
    </AbsoluteFill>
  );
};

export default LiquidGlassOverlay;